// Minimise the sum of weighted completion times (Smith's rule).
// Optimal order is proven by an adjacent-swap exchange argument.
long long schedule(vector<pair<long long,long long>> jobs) {   // {p, w}
    sort(jobs.begin(), jobs.end(), [](auto& a, auto& b){
        return a.first * b.second < b.first * a.second;        // p_a/w_a < p_b/w_b
    });
    long long t = 0, cost = 0;
    for (auto& [p, w] : jobs) {
        t += p;
        cost += w * t;              // completion time * weight
    }
    return cost;
}

class Solution {
public:
    vector<vector<int>> reconstructQueue(vector<vector<int>>& people) {
        sort(people.begin(), people.end(), [](auto& a, auto& b){ return a[0] != b[0] ? a[0] > b[0] : a[1] < b[1]; });
        vector<vector<int>> res;
        for (auto& p : people) res.insert(res.begin() + p[1], p);
        return res;
    }
};

class Solution:
    def reconstructQueue(self, people: list[list[int]]) -> list[list[int]]:
        people.sort(key=lambda p: (-p[0], p[1]))
        res = []
        for p in people:
            res.insert(p[1], p)
        return res

class Solution {
public:
    int connectSticks(vector<int>& sticks) {
        priority_queue<int, vector<int>, greater<>> pq(sticks.begin(), sticks.end());
        int cost = 0;
        while (pq.size() > 1) {
            int a = pq.top(); pq.pop();
            int b = pq.top(); pq.pop();
            cost += a + b; pq.push(a + b);
        }
        return cost;
    }
};

class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> cnt(26, 0);
        for (char c : tasks) cnt[c - 'A']++;
        int f = *max_element(cnt.begin(), cnt.end());
        int c = count(cnt.begin(), cnt.end(), f);
        return max((int)tasks.size(), (f - 1) * (n + 1) + c);
    }
};

from collections import Counter
class Solution:
    def leastInterval(self, tasks: list[str], n: int) -> int:
        cnt = Counter(tasks)
        f = max(cnt.values())
        c = sum(1 for v in cnt.values() if v == f)
        return max(len(tasks), (f - 1) * (n + 1) + c)

class Solution {
public:
    int findContentChildren(vector<int>& g, vector<int>& s) {
        sort(g.begin(), g.end()); sort(s.begin(), s.end());
        int i = 0, j = 0;
        while (i < (int)g.size() && j < (int)s.size()) {
            if (s[j] >= g[i]) i++;
            j++;
        }
        return i;
    }
};

class Solution:
    def findContentChildren(self, g: list[int], s: list[int]) -> int:
        g.sort(); s.sort()
        i = j = 0
        while i < len(g) and j < len(s):
            if s[j] >= g[i]:
                i += 1
            j += 1
        return i

class Solution {
public:
    int numRescueBoats(vector<int>& people, int limit) {
        sort(people.begin(), people.end());
        int i = 0, j = people.size() - 1, boats = 0;
        while (i <= j) {
            if (people[i] + people[j] <= limit) i++;
            j--; boats++;
        }
        return boats;
    }
};

class Solution:
    def numRescueBoats(self, people: list[int], limit: int) -> int:
        people.sort()
        i, j, boats = 0, len(people) - 1, 0
        while i <= j:
            if people[i] + people[j] <= limit:
                i += 1
            j -= 1
            boats += 1
        return boats
